style.css:
@-moz-document domain("thomann.de"), domain("www.thomann.de") {
/* Ersetzt den Text "Service" durch "S e r v i c e" */
  *:not(script):not(style) {
    font-family: inherit;
  }
  *:not(script):not(style)::before {
    content: attr(data-original-text);
  }
  *:not(script):not(style)[data-original-text*="Service"]::before {
    content: "S e r v i c e";
  }
}
